#include "BackgroundGen.h"
#include <cmath>
#include "Thumbnail.h"
#include <cstdio>
#include "ShaderSource.h"// generated by tools/gen_shader.py

// The host sees major.minor (FFGL keeps no patch number). A new minor lets Resolume
// notice an updated plugin (thumbnail, description) instead of reusing cached info.
#ifndef SOUZ_VERSION_MAJOR
#define SOUZ_VERSION_MAJOR 1
#endif
#ifndef SOUZ_VERSION_MINOR
#define SOUZ_VERSION_MINOR 16
#endif

using namespace ffglex;

// 4-char unique id, 16-char name: both are what Resolume uses to identify the plugin.
// If you ever ship a different plugin, change the id so the two never clash.
static CFFGLPluginInfo PluginInfo(
	PluginFactory< BackgroundGen >,// Create method
	"ABGE",                        // Plugin unique ID
	"Souz Content-BG",              // Plugin name (max 16 chars)
	2,                             // API major version number
	1,                             // API minor version number
	SOUZ_VERSION_MAJOR,            // Plugin major version number (from VERSION via CMake)
	SOUZ_VERSION_MINOR,            // Plugin minor version number (from VERSION via CMake)
	FF_SOURCE,                     // Plugin type
	"Animated backgrounds: fog, lava, neon, aurora, smoke, gradients, lasers, lines, blocks, shapes, ink",
	"Procedural background generator. Pure GPU shader, no video files." );

BackgroundGen::BackgroundGen()
{
	// The quickstart framework prepends the version line, the built-in uniforms and one
	// uniform per parameter to our shader. We only need one extra: the integrated time.
	fragmentShaderCodeStart += "\n\t\tuniform float animTime;\n";

	// AddParam(...) calls for every parameter (Engine, Shape, Palette, Scale, ... Color1-4).
	// Order here == order in the Resolume UI; names double as GLSL uniform names.
#include "ParamsGenerated.inc"

	speedParam   = GetParam( "Speed" );
	reverseParam = GetParam( "Reverse" );
	speedIndex   = souz::PanelState::Find( "Speed" );
	reverseIndex = souz::PanelState::Find( "Reverse" );
	engineIndex  = souz::PanelState::Find( "Engine" );

	// Append: do not change any existing parameter indices or saved compositions.

    SetFragmentShader( BuildBackgroundShader() );
}

BackgroundGen::~BackgroundGen() { Clean(); }

FFResult BackgroundGen::Init()
{
    // SDK creates a prototype to enumerate parameters. Starting only in Init()
    // avoids a server for that prototype or for a failed GL initialization.
    if(!panel) {
        try { panel = std::make_unique<souz::PanelServer>(panelState); }
        catch(const std::exception&) { FFGLLog::LogToHost("Souz Content: unable to start web panel"); }
    }
    return FF_SUCCESS; // A network failure must not break video output.
}

void BackgroundGen::Clean() { panel.reset(); engineFade = {}; sceneFade = {}; scenePublishPending = false; }

FFResult BackgroundGen::SetFloatParameter(unsigned int index, float value)
{
    if(index==openIndex) {
        if(value>0.5f && panel) panel->Open();
        return FF_SUCCESS;
    }
    if(index>openIndex) --index;
    if(index<souz::ParamCount)
        return panelState.Set(index,value,false) ? FF_SUCCESS : FF_FAIL;
    return FF_FAIL;
}

float BackgroundGen::GetFloatParameter(unsigned int index)
{
    if(index==openIndex) return 0.0f;
    if(index>openIndex) --index;
    if(index<souz::ParamCount) return panelState.Get(index);
    return 0.0f;
}

char* BackgroundGen::GetParameterDisplay(unsigned int index)
{
    const auto hostIndex=index;
    if(index==openIndex) return ffglqs::Source::GetParameterDisplay(index);
    if(index>openIndex) --index;
    if(index<souz::ParamCount) {
        const auto name=std::string(souz::ParamDefs[index].name);
        const float v=GetFloatParameter(hostIndex);
        if(name=="Brightness"||name=="Contrast"||name=="Saturation")
            std::snprintf(paramDisplay,sizeof paramDisplay,"%+.0f",(v-souz::ParamDefs[index].defaultValue)*200.0f);
        else std::snprintf(paramDisplay,sizeof paramDisplay,"%.3f",v);
        return paramDisplay;
    }
    if(index>=params.size()) return nullptr;
    return ffglqs::Source::GetParameterDisplay(index);
}

void BackgroundGen::ApplyPanelParams()
{
    for(size_t i=0;i<souz::ParamCount;++i) {
        const auto snapshot=panelState.values[i].Snapshot();
        if(snapshot==appliedParams[i]) continue;
        const auto hostIndex=static_cast<unsigned int>(i>=openIndex ? i+1 : i);
        params[hostIndex]->SetValue(souz::AtomicParam::Value(snapshot));
        appliedParams[i]=snapshot;
        if(souz::AtomicParam::FromWeb(snapshot)) RaiseParamEvent(hostIndex,FF_EVENT_FLAG_VALUE);
    }
}

souz::SceneValues BackgroundGen::CurrentValues() const
{
    souz::SceneValues v{};
    for(size_t i=0;i<souz::ParamCount;++i) v[i]=panelState.Get(i);
    return v;
}

void BackgroundGen::CommitTake()
{
    souz::SceneRequest take;
    const auto outgoing=CurrentValues();
    const auto generation=panelState.scene.TryTake(take,outgoing,animTime);
    if(!generation) return;
    // The outgoing scene is what is on screen now; if a TAKE interrupts a
    // running crossfade, the incoming scene of that fade becomes the outgoing one.
    sceneFade.Start(generation,outgoing,animTime,take.duration);
    for(size_t i=0;i<souz::ParamCount;++i) panelState.Set(i,take.values[i],true);
    ApplyPanelParams();           // host sees the new values (RaiseParamEvent)
    animTime=take.time;           // PVW clock continues on PGM without a jump
    const int engine=static_cast<int>(take.values[engineIndex]+0.5f);
    engineFade.from=engineFade.to=engine;engineFade.progress=1;engineFade.initialized=true;
    scenePublishPending=true;
}

FFResult BackgroundGen::ProcessOpenGL(ProcessOpenGLStruct* input)
{
    ApplyPanelParams();
    CommitTake();
    return ffglqs::Source::ProcessOpenGL(input);
}

void BackgroundGen::SendScene(const souz::SceneValues& values, double time, float opacity)
{
    for(size_t i=0;i<souz::ParamCount;++i) {
        const auto hostIndex=static_cast<unsigned int>(i>=openIndex ? i+1 : i);
        if(params[hostIndex]->GetType()==FF_TYPE_BOOLEAN) shader.Set(souz::ParamDefs[i].name,values[i]>0.5f ? 1 : 0);
        else shader.Set(souz::ParamDefs[i].name,values[i]);
    }
    shader.Set("animTime",static_cast<float>(time));
    shader.Set("sceneOpacity",opacity);
}

FFResult BackgroundGen::Render(ProcessOpenGLStruct*)
{
    // The base class bound the shader and uploaded the live (incoming) scene.
    const bool engineFading=engineFade.progress<1.0f && engineFade.from!=engineFade.to;
    if(!sceneFade.active && !engineFading) {
        shader.Set("sceneOpacity",1.0f);
        quad.Draw();
        return FF_SUCCESS;
    }
    // Two passes, at most two engines per frame: outgoing scene opaque,
    // incoming scene blended with smoothstep(progress) (same as the panel preview).
    souz::SceneValues outgoing;double outgoingTime;float progress;
    if(sceneFade.active) { outgoing=sceneFade.from;outgoingTime=sceneFade.fromTime;progress=sceneFade.progress; }
    else { outgoing=CurrentValues();outgoing[engineIndex]=float(engineFade.from);outgoingTime=animTime;progress=engineFade.progress; }

    const GLboolean blend=glIsEnabled(GL_BLEND);
    GLint srcRGB=GL_ONE,dstRGB=GL_ZERO,srcAlpha=GL_ONE,dstAlpha=GL_ZERO;
    glGetIntegerv(GL_BLEND_SRC_RGB,&srcRGB);glGetIntegerv(GL_BLEND_DST_RGB,&dstRGB);
    glGetIntegerv(GL_BLEND_SRC_ALPHA,&srcAlpha);glGetIntegerv(GL_BLEND_DST_ALPHA,&dstAlpha);

    glDisable(GL_BLEND);
    SendScene(outgoing,outgoingTime,1.0f);
    quad.Draw();

    SendParams(shader);                       // restore the live scene
    shader.Set("animTime",static_cast<float>(animTime));
    shader.Set("sceneOpacity",souz::SceneFade::Weight(progress));
    glEnable(GL_BLEND);
    glBlendFuncSeparate(GL_SRC_ALPHA,GL_ONE_MINUS_SRC_ALPHA,GL_ONE,GL_ONE_MINUS_SRC_ALPHA);
    quad.Draw();

    glBlendFuncSeparate(GLenum(srcRGB),GLenum(dstRGB),GLenum(srcAlpha),GLenum(dstAlpha));
    if(!blend) glDisable(GL_BLEND);
    return FF_SUCCESS;
}

void BackgroundGen::Update()
{
	// deltaTime is the wall-clock time since the previous frame. It can be huge on the very
	// first frame or after the clip was paused, so clamp it.
	float dt = deltaTime;
	if( dt < 0.0f || dt > 0.25f )
		dt = 1.0f / 60.0f;

	// Speed 0..1 -> 0x..4x with a quadratic curve (fine control near the slow end).
	float s = speedParam ? speedParam->GetValue() : 0.35f;
	s       = s * s * 4.0f;

	const bool reverse = reverseParam && reverseParam->GetValue() > 0.5f;
	animTime += static_cast< double >( dt ) * s * ( reverse ? -1.0 : 1.0 );

	sceneFade.Advance(dt,speedIndex,reverseIndex);
	if(scenePublishPending || sceneFade.generation) {
		const bool done=!sceneFade.active;
		if(panelState.scene.TryPublish(sceneFade.generation,sceneFade.progress,sceneFade.fromTime,done)) {
			scenePublishPending=false;
			if(done) sceneFade.generation=0;
		}
	}

	engineFade.Advance(static_cast<int>(GetParam("Engine")->GetValue()+0.5f), dt);
    // One atomic publication keeps source, target and progress coherent.
    panelState.PublishFade(engineFade.from, engineFade.to, engineFade.progress);

	// The shader is already bound by Plugin::ProcessOpenGL when Update() runs.
	shader.Set( "animTime", static_cast< float >( animTime ) );
    panelState.animationTime.Set(static_cast<float>(animTime), false);
    panelState.beatPhase.Set(barPhase, false);
    panelState.tempo.Set(bpm, false);
    panelState.width.Set(float(currentViewport.width), false);
    panelState.height.Set(float(currentViewport.height), false);
}
